package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.util.*;
/** Real in-app preview driven by the same PdfService card renderer. */
public final class PrintPreviewActivity extends Activity {private ArrayList<String[]> cards=new ArrayList<>();private CardTemplate template;private Bitmap background;private PreviewView preview;@Override public void onCreate(Bundle b){super.onCreate(b);template=new TemplateStore(this).get();try{if(!template.imageUri.isEmpty())try(java.io.InputStream in=getContentResolver().openInputStream(Uri.parse(template.imageUri))){background=BitmapFactory.decodeStream(in);}}catch(Exception ignored){}try{String raw=new BatchStore(this).loadBatch("current");for(String l:(raw==null?"":raw).split("\\n")){String[]x=l.split("\\|",-1);if(x.length==4)cards.add(new String[]{x[0],x[1],x[2]});}}catch(Exception ignored){}LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(12,16,12,24);p.setBackgroundColor(Color.rgb(237,244,250));p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);preview=new PreviewView(this);p.addView(preview,new LinearLayout.LayoutParams(-1,0,1));Button export=new Button(this);export.setText("تصدير PDF للقالب الحالي");export.setOnClickListener(v->export());p.addView(export);Button share=new Button(this);share.setText("مشاركة PDF بعد الحفظ");share.setOnClickListener(v->export());p.addView(share);setContentView(p);UiTheme.apply(this);}
 private void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"smart-manager-vouchers.pdf");startActivityForResult(i,44);}@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==44&&c==RESULT_OK&&d!=null)try{PdfService.write(this,d.getData(),cards,template);Toast.makeText(this,"تم إنشاء PDF",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"فشل PDF",Toast.LENGTH_LONG).show();}}
 private final class PreviewView extends View{private final Paint p=new Paint(3);PreviewView(Context c){super(c);setBackgroundColor(Color.WHITE);}protected void onDraw(Canvas c){super.onDraw(c);if(cards.isEmpty()){p.setColor(Color.DKGRAY);p.setTextSize(28);c.drawText("لا توجد كروت محفوظة للمعاينة",40,80,p);return;}float scale=Math.min(getWidth()/(float)template.paperW,getHeight()/(float)template.paperH);c.save();c.scale(scale,scale);for(int i=0;i<Math.min(cards.size(),template.perPage());i++){float w=(template.paperW-2*template.margin-(template.columns-1)*template.gap)/(float)template.columns,h=(template.paperH-2*template.margin-(template.rows-1)*template.gap)/(float)template.rows;PdfService.drawCard(c,cards.get(i),template,background,template.margin+(i%template.columns)*(w+template.gap),template.margin+(i/template.columns)*(h+template.gap),w,h);}c.restore();}}
}
